const REPORT_BODY = "\n<div class=\"sheet\">\n  <header class=\"masthead\">\n    <span class=\"corner l\">hapi 内部统计 · 非卖品</span>\n    <span class=\"corner r\" id=\"mh-window\"></span>\n    <div class=\"english\">The Skill Evening Post</div>\n    <h1>器物晚报</h1>\n    <div class=\"sub\">—— skill 使用纪要 · 你的工具房，每晚盘点一次 ——</div>\n    <div class=\"dateline\">\n      <span>统计窗口 <strong id=\"dl-range\"></strong></span>\n      <span>记录 <strong id=\"dl-total\"></strong> 条</span>\n      <span>显式 <strong id=\"dl-explicit\"></strong> · 自动 <strong id=\"dl-model\"></strong> · 命令 <strong id=\"dl-command\"></strong></span>\n      <span>体量不等于正确性</span>\n    </div>\n  </header>\n\n  <div class=\"front\">\n    <div class=\"story\">\n      <div class=\"kicker\">头条 · 本期综述</div>\n      <h2 id=\"front-title\"></h2>\n      <p class=\"dek\" id=\"front-dek\"></p>\n      <div id=\"front-body\"></div>\n      <div class=\"coda\">—— 本文由本报资料室依据窗口内全部使用记录整理（正式版由模型按当日数据撰写）</div>\n    </div>\n    <div class=\"front-side\">\n      <div class=\"cap\">本期总唤起</div>\n      <div class=\"figures-row\">\n        <div class=\"big\"><span id=\"front-num\"></span> <span class=\"unit\">次</span></div>\n        <p class=\"figures-note\" id=\"front-note\"></p>\n      </div>\n      <div class=\"bullets\" id=\"front-bullets\"></div>\n    </div>\n  </div>\n\n  <div class=\"quad\">\n    <section>\n      <div class=\"slab-head\"><h2>本报要闻</h2><span class=\"note\">一句一事</span></div>\n      <div class=\"briefing\" id=\"briefing\"></div>\n    </section>\n    <section>\n      <div class=\"slab-head\"><h2>时段热力</h2><span class=\"note\" id=\"heat-range\"></span></div>\n      <div class=\"heatmap\" id=\"heatmap\"></div>\n      <p class=\"edit-note\" id=\"heat-note\"></p>\n    </section>\n    <section>\n      <div class=\"slab-head\"><h2>二十四小时分布</h2><span class=\"note\">全窗口合计</span></div>\n      <figure>\n        <svg id=\"hours\" viewBox=\"0 0 560 140\" role=\"img\" aria-label=\"24 小时使用分布柱状图\"></svg>\n        <figcaption>横轴本地小时，纵轴次数；墨柱为计数，红色虚线为峰值参考。</figcaption>\n        <p class=\"edit-note\" id=\"hours-note\"></p>\n      </figure>\n    </section>\n    <section>\n      <div class=\"slab-head\"><h2 id=\"trend-title\"></h2><span class=\"note\">按周折线 · 周一为界</span></div>\n      <figure>\n        <svg id=\"weeks\" viewBox=\"0 0 560 160\" role=\"img\" aria-label=\"按周使用次数折线图\"></svg>\n        <figcaption>横轴周起始日，纵轴次数；红点为峰值周。</figcaption>\n        <p class=\"edit-note\" id=\"weeks-note\"></p>\n      </figure>\n    </section>\n  </div>\n\n  <section id=\"what-section\">\n    <div class=\"slab-head\"><h2>唤起实录 <button class=\"pin-btn\" id=\"pin-btn\" data-tip=\"钉住本版，滚动时不随之移动\" title=\"钉住本版\"></button></h2>\n      <span class=\"note\">本版逐条回放窗口内每一次器物唤起：谁发起（你/模型/命令）、什么时辰、说了什么 · 左栏选器物可单看一路</span>\n    </div>\n    <div class=\"split\">\n      <nav class=\"index\">\n        <div class=\"head\">索引 · skill 与命令</div>\n        <div id=\"skill-index\"></div>\n      </nav>\n      <div class=\"column\">\n        <div id=\"analysis\"></div>\n        <div class=\"briefs-head\" id=\"feed-count\"></div>\n        <div class=\"briefs\" id=\"feed\"></div>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"slab-head\"><h2>读者来信 · 自定义分析目标</h2>\n      <span class=\"note\">/hapi-metrics purpose <目标文字> 添加 · 出报告时按目标生成分析</span>\n    </div>\n    <div class=\"letters\" id=\"goals\"></div>\n    <div class=\"slab-head\" style=\"margin-top: 32px;\"><h2>本报建议 · 值得登记的分析目标</h2>\n      <span class=\"note\">由窗口数据归纳 · 登记后下期起逐期生成分析</span>\n    </div>\n    <div class=\"suggests\" id=\"suggests\"></div>\n  </section>\n\n  <section>\n    <div class=\"slab-head\"><h2>新到器物 · 架上蒙尘待君一试</h2>\n      <span class=\"note\">零使用与低频 · 结合你最近的活儿对号入座</span>\n    </div>\n    <div class=\"shophasics\" id=\"wares\"></div>\n  </section>\n\n  <section>\n    <div class=\"slab-head\"><h2>本报更新</h2><span class=\"note\">相对上一期晚报</span></div>\n    <div class=\"update-log\" id=\"update-log\"></div>\n  </section>\n\n  <footer class=\"colophon\">\n    <span>器物晚报 · /hapi-metrics skills --eli60</span>\n    <span id=\"colophon-date\"></span>\n  </footer>\n</div>\n<div id=\"tip\"></div>\n\n";
/* 原型渲染脚本（DATA 声明已剥离，由 renderSkillsReport 注入） */
const REPORT_SCRIPT = "\n/* 文章与分析文字在原型阶段为手写示例；正式版由离线管线（recap 同款选模）按当日数据撰写 */\n\nconst esc = s => String(s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\");\nconst fmt = n => n >= 1e6 ? (n/1e6).toFixed(1)+\"M\" : n >= 1e3 ? (n/1e3).toFixed(1)+\"k\" : String(Math.round(n));\nconst dayLabel = ts => { const d = new Date(ts); return `${String(d.getMonth()+1).padStart(2,\"0\")}-${String(d.getDate()).padStart(2,\"0\")}`; };\nconst whenLabel = ts => { const d = new Date(ts); return `${dayLabel(ts)} ${String(d.getHours()).padStart(2,\"0\")}:${String(d.getMinutes()).padStart(2,\"0\")}`; };\nconst ORIGIN = { builtin: \"内置\", user: \"外置\", project: \"项目\" };\nconst SIG = { explicit: [\"显式\", \"explicit\"], model: [\"自动\", \"model\"], command: [\"命令\", \"command\"] };\n\ndocument.getElementById(\"mh-window\").textContent = DATA.window.start + \" — \" + DATA.window.end;\ndocument.getElementById(\"dl-range\").textContent = `${DATA.window.start} ~ ${DATA.window.end}（${DATA.window.days} 天）`;\ndocument.getElementById(\"dl-total\").textContent = DATA.totals.events;\ndocument.getElementById(\"dl-explicit\").textContent = DATA.totals.explicit;\ndocument.getElementById(\"dl-model\").textContent = DATA.totals.model;\ndocument.getElementById(\"dl-command\").textContent = DATA.totals.command ?? 0;\ndocument.getElementById(\"colophon-date\").textContent = `生成于 ${DATA.generatedAt} · 文字为原型示例`;\n\n/* ——— 头条文章：本报讯只在首段（报纸电头惯例） ——— */\ndocument.getElementById(\"front-num\").textContent = fmt(DATA.totals.events);\ndocument.getElementById(\"front-title\").textContent = DATA.frontPage.title;\ndocument.getElementById(\"front-dek\").textContent = DATA.frontPage.dek;\ndocument.getElementById(\"front-body\").innerHTML =\n  DATA.frontPage.paragraphs.map((p, i) =>\n    i === 0 ? `<p><span class=\"lead-in\">本报讯</span> ${esc(p)}</p>` : `<p>${esc(p)}</p>`\n  ).join(\"\");\n\ndocument.getElementById(\"front-note\").textContent =\n  `这个数目是窗口内每一次器物唤起与命令敲下的总和：你亲手点名的、模型自己取用的、命令行敲下的，都记在内。它不衡量对错，不评价勤懒，只忠实记录这座工具房的忙碌程度——哪几件被频繁取用，哪几件在架上蒙尘，哪些时辰灯火最亮，翻完这一版便有答案。口径与逐条明细，见下方各版。`;\n\n// 编辑室手记：确定性小数据，填满右栏\n(function deskNote() {\n  const sorted = [...DATA.records].sort((a, b) => a.ts - b.ts);\n  const first = sorted[0], last = sorted[sorted.length - 1];\n  const bySkill = new Map();\n  for (const r of DATA.records) bySkill.set(r.skill, (bySkill.get(r.skill) ?? 0) + 1);\n  const el = document.createElement(\"div\");\n  el.className = \"desk-note\";\n  el.innerHTML = `<div class=\"head\">编辑室手记</div>` +\n    `<p>本期的第一声唤起落在 <strong>${whenLabel(first.ts)}</strong>（${esc(first.skill)}），` +\n    `最后一声收在 <strong>${whenLabel(last.ts)}</strong>（${esc(last.skill)}）——头尾相隔 ` +\n    `${Math.round((last.ts - first.ts) / 3600000)} 个小时。</p>` +\n    `<p>架上现役器物 ${DATA.totals.skills} 件，本期登场 ${bySkill.size} 件；` +\n    `尚有 ${DATA.idle.length} 件整月未动，本报已在末版递上荐语。</p>` +\n    `<p>统计口径与往期不同处，见「本报更新」版。</p>`;\n  document.getElementById(\"front-bullets\").after(el);\n})();\n\ndocument.getElementById(\"front-bullets\").innerHTML = DATA.frontBullets\n  .map(([l, v, why]) => `<div><span class=\"no\">▲</span>${l} <span class=\"n\">${esc(v)}</span>${why ? `<span class=\"why\">${esc(why)}</span>` : \"\"}</div>`).join(\"\");\n\ndocument.getElementById(\"briefing\").innerHTML = DATA.briefing\n  .map(line => `<div><span class=\"no\">▲</span>${esc(line)}</div>`).join(\"\");\n\n/* ——— tooltip ——— */\nconst tip = document.getElementById(\"tip\");\ndocument.addEventListener(\"mouseover\", (event) => {\n  const host = event.target.closest(\"[data-tip]\");\n  tip.style.opacity = host ? 1 : 0;\n  if (host) tip.textContent = host.dataset.tip;\n});\ndocument.addEventListener(\"mousemove\", (event) => {\n  if (tip.style.opacity !== \"1\") return;\n  tip.style.left = Math.min(event.clientX + 14, window.innerWidth - tip.offsetWidth - 8) + \"px\";\n  tip.style.top = event.clientY + 16 + \"px\";\n});\n\n/* ——— 热力：窗口全日历补齐 ——— */\n(function heatmap() {\n  const max = Math.max(1, ...DATA.days.flatMap(d => d.hours));\n  document.getElementById(\"heat-range\").textContent = `${DATA.days[0]?.day ?? \"\"} 起`;\n  const head = `<div class=\"h\"></div>` + Array.from({length:24},(_,h)=>`<div class=\"h\">${h}</div>`).join(\"\");\n  let cellIndex = 0;\n  const rows = DATA.days.map(d => `<div class=\"lab\">${d.day.slice(5)}</div>` + d.hours.map(v => {\n    if (!v) return `<div class=\"c\" data-tip=\"${d.day} · 0 次\"></div>`;\n    const ink = [0.18,0.36,0.55,0.75,1][Math.min(4, Math.ceil(v/max*4))];\n    return `<div class=\"c pop\" data-tip=\"${d.day} · ${v} 次\" style=\"background:rgba(23,21,18,${ink});animation-delay:${(cellIndex++)*4}ms\"></div>`;\n  }).join(\"\")).join(\"\");\n  document.getElementById(\"heatmap\").innerHTML = head + rows;\n\n  const usedDays = DATA.days.filter(d => d.hours.some(v => v > 0));\n  const flat = DATA.days.flatMap(d => d.hours.map((v, h) => ({ day: d.day, h, v })));\n  const peak = flat.reduce((a, b) => (b.v > a.v ? b : a), flat[0]);\n  const byDay = new Map(DATA.days.map(d => [d.day, d.hours.reduce((a, b) => a + b, 0)]));\n  const busy = [...byDay.entries()].reduce((a, b) => (b[1] > a[1] ? b : a));\n  const quietDays = DATA.days.length - usedDays.length;\n  const atPeakHour = DATA.records.filter(r => new Date(r.ts).getHours() === peak.h);\n  const peakHourCount = new Map();\n  for (const r of atPeakHour) peakHourCount.set(r.skill, (peakHourCount.get(r.skill) ?? 0) + 1);\n  const peakTop = [...peakHourCount.entries()].sort((a, b) => b[1] - a[1])[0];\n  document.getElementById(\"heat-note\").innerHTML =\n    `峰值出现在 <strong>${peak.h}:00–${peak.h + 1}:00</strong>（该时段全窗口共 ${peak.v} 次，其中 <strong>${peakTop?.[0] ?? \"—\"}</strong> 独占 ${peakTop?.[1] ?? 0} 次）；` +\n    `最忙的一天是 <strong>${busy[0]}</strong>（${busy[1]} 次）` +\n    (quietDays > 0 ? `；另有 ${quietDays} 天整日未开张，格子全空。` : \"。\") +\n    `鼠标悬停可看逐格读数。`;\n})();\n\n/* ——— 柱状（24h）——— */\nfunction svgBars(el, pairs, unit) {\n  const W = 560, H = 140, padB = 24, padT = 14, padL = 34;\n  const max = Math.max(1, ...pairs.map(p => p[1]));\n  const baseline = H - padB;\n  const plotW = W - padL - 8;\n  const slot = plotW / pairs.length;\n  const barW = Math.max(2, Math.min(28, slot - 4));\n  const yOf = v => baseline - (v / max) * (baseline - padT);\n  const ticks = [0, max / 2, max].map(v => {\n    const y = yOf(v);\n    const line = v === 0 ? \"\" :\n      `<line x1=\"${padL}\" x2=\"${W - 8}\" y1=\"${y}\" y2=\"${y}\" stroke=\"currentColor\" opacity=\"0.1\"></line>`;\n    return line + `<text x=\"${padL - 6}\" y=\"${y + 3}\" text-anchor=\"end\" font-size=\"9\" fill=\"currentColor\" opacity=\"0.55\">${fmt(Math.round(v))}</text>`;\n  }).join(\"\");\n  const labelEvery = Math.max(1, Math.ceil(pairs.length / 14));\n  const peak = Math.max(...pairs.map(p => p[1]));\n  const bars = pairs.map(([label, v], i) => {\n    const x = padL + i * slot + (slot - barW) / 2;\n    const y = yOf(v);\n    const tick = i % labelEvery === 0\n      ? `<text x=\"${x + barW / 2}\" y=\"${H - 6}\" text-anchor=\"middle\" font-size=\"9\" fill=\"currentColor\" opacity=\"0.6\">${esc(label)}</text>` : \"\";\n    const hit = `<rect class=\"hit\" data-tip=\"${esc(label)} · ${v} ${unit}\" x=\"${padL + i * slot}\" y=\"${padT}\" width=\"${slot}\" height=\"${baseline - padT}\" fill=\"transparent\"></rect>`;\n    const bar = v === 0 ? \"\" :\n      `<rect class=\"grow\" data-tip=\"${esc(label)} · ${v} ${unit}\" style=\"animation-delay:${i * 24}ms\" x=\"${x}\" y=\"${y}\" width=\"${barW}\" height=\"${baseline - y}\" fill=\"currentColor\"></rect>`;\n    return tick + hit + bar;\n  }).join(\"\");\n  const peakLine = peak > 0\n    ? `<line x1=\"${padL}\" x2=\"${W - 8}\" y1=\"${yOf(peak)}\" y2=\"${yOf(peak)}\" stroke=\"#a02c20\" stroke-width=\"1\" stroke-dasharray=\"4 3\" opacity=\"0.7\"></line>` : \"\";\n  el.innerHTML = ticks + bars +\n    `<line x1=\"${padL}\" x2=\"${W - 8}\" y1=\"${baseline}\" y2=\"${baseline}\" stroke=\"currentColor\" stroke-width=\"1\"></line>` + peakLine;\n}\nsvgBars(document.getElementById(\"hours\"), DATA.hours.map((v, h) => [`${h}时`, v]), \"次\");\n\n/* ——— 折线（窗口走势）——— */\n(function weekLine() {\n  const svg = document.getElementById(\"weeks\");\n  const W = 560, H = 160, padB = 26, padT = 18, padL = 40;\n  const pairs = DATA.weeks.map(w => [w.weekStart.slice(5), w.count]);\n  const max = Math.max(1, ...pairs.map(p => p[1]));\n  const baseline = H - padB;\n  const plotW = W - padL - 16;\n  const step = pairs.length > 1 ? plotW / (pairs.length - 1) : 0;\n  const xOf = i => padL + i * step;\n  const yOf = v => baseline - (v / max) * (baseline - padT);\n  const peakIdx = pairs.reduce((best, [, v], i) => (v > pairs[best][1] ? i : best), 0);\n  const grid = [0, max / 2, max].map(v => {\n    const y = yOf(v);\n    return (v === 0 ? \"\" : `<line x1=\"${padL}\" x2=\"${W - 10}\" y1=\"${y}\" y2=\"${y}\" stroke=\"currentColor\" opacity=\"0.1\"></line>`) +\n      `<text x=\"${padL - 6}\" y=\"${y + 3}\" text-anchor=\"end\" font-size=\"9\" fill=\"currentColor\" opacity=\"0.55\">${fmt(Math.round(v))}</text>`;\n  }).join(\"\");\n  const path = pairs.map(([, v], i) => `${i === 0 ? \"M\" : \"L\"}${xOf(i)},${yOf(v)}`).join(\" \");\n  const dots = pairs.map(([, v], i) =>\n    `<circle class=\"dot${i === peakIdx ? \" peak\" : \"\"} dot-in\" style=\"animation-delay:${200 + i * 120}ms\" data-tip=\"周${pairs[i][0]} · ${v} 次\" cx=\"${xOf(i)}\" cy=\"${yOf(v)}\" r=\"4\"></circle>` +\n    `<text x=\"${xOf(i)}\" y=\"${yOf(v) - 10}\" text-anchor=\"middle\" font-size=\"10\" fill=\"currentColor\" opacity=\"0.75\">${v}</text>` +\n    `<text x=\"${xOf(i)}\" y=\"${H - 6}\" text-anchor=\"middle\" font-size=\"9\" fill=\"currentColor\" opacity=\"0.6\">${pairs[i][0]}</text>` +\n    `<rect class=\"hit\" data-tip=\"周${pairs[i][0]} · ${v} 次\" x=\"${xOf(i) - step / 2}\" y=\"${padT}\" width=\"${Math.max(step, 12)}\" height=\"${baseline - padT}\" fill=\"transparent\"></rect>`\n  ).join(\"\");\n  svg.innerHTML = grid +\n    `<path class=\"line-main draw\" d=\"${path}\"></path>` + dots +\n    `<line x1=\"${padL}\" x2=\"${W - 10}\" y1=\"${baseline}\" y2=\"${baseline}\" stroke=\"currentColor\" stroke-width=\"1\"></line>`;\n})();\n\n/* ——— 编者按 ——— */\n(function annotateHours() {\n  const seg = (from, to) => DATA.hours.slice(from, to).reduce((a, b) => a + b, 0);\n  const total = Math.max(1, DATA.totals.events);\n  const pct = n => Math.round((n / total) * 100);\n  const quietHour = DATA.hours.indexOf(Math.min(...DATA.hours));\n  document.getElementById(\"hours-note\").innerHTML =\n    `凌晨（00–06）占 <strong>${pct(seg(0, 6))}%</strong> · 上午（06–12）<strong>${pct(seg(6, 12))}%</strong> · ` +\n    `下午（12–18）<strong>${pct(seg(12, 18))}%</strong> · 夜间（18–24）<strong>${pct(seg(18, 24))}%</strong>。` +\n    `峰在 <strong>${DATA.peakHour} 时</strong>（${DATA.hours[DATA.peakHour]} 次），谷在 <strong>${quietHour} 时</strong>（${DATA.hours[quietHour]} 次）。`;\n})();\n(function annotateWeeks() {\n  const weeks = DATA.weeks;\n  document.getElementById(\"trend-title\").textContent = `${DATA.window.days} 天走势`;\n  if (weeks.length < 2) return;\n  const first = weeks[0].count, last = weeks[weeks.length - 1].count;\n  const direction = last >= first ? \"升\" : \"回落\";\n  const delta = first === 0 ? \"—\" : Math.abs(Math.round((last - first) / first * 100)) + \"%\";\n  const busiest = weeks.reduce((a, b) => (b.count > a.count ? b : a));\n  document.getElementById(\"weeks-note\").innerHTML =\n    `首周 ${first} 次 → 末周 ${last} 次，${direction} ${delta}；峰值在 <strong>${busiest.weekStart.slice(5)}</strong> 那一周` +\n    `（${busiest.count} 次，其中 <strong>${esc(DATA.skills[0]?.skill ?? \"\")}</strong> 出力最多）。` +\n    `换窗口（--since）后本图与标题随之更新。`;\n})();\n\n/* ——— 干了什么 ——— */\nfunction fixedGoals() {\n  const top = DATA.skills[0];\n  const partner = DATA.partners?.[top?.skill];\n  return [\n    { title: \"意图画像 · 它通常被用来干什么\", text: \"（示例文本）显式原话聚出两类意图：过半是「看结构、理流程」的侦查类请求，其余为方案对比；自动加载的会话线索（「当日正在办」）与此吻合——自动占比高的器物不再只按显式口径断言。\" },\n    { title: \"趋势与节奏 · 用量在升还是在降\", text: \"（示例文本）前半月与后半月之比约 1:2，间隔中位 3.5 天；时段双峰，10:00–12:00 与 22:00 后各占三成。\" },\n    { title: \"显式/自动与一致性 · 谁在用它\", text: \"（示例文本）显式为主，自动加载多出现在会话开头（探索先行条款的产物）；用法与登记用途一致，未见偏移。\" },\n    { title: \"搭档 · 它常和谁一起出场\", text: partner\n        ? `与 <strong>${esc(partner.partner)}</strong> 同会话出现 ${partner.count} 次，是它最固定的搭子——两件器物一问一档，构成工作流里的固定两步。（示例文本）`\n        : \"（示例文本）窗口内未见固定搭档。\" },\n  ];\n}\n\nconst indexEl = document.getElementById(\"skill-index\");\nconst feedEl = document.getElementById(\"feed\");\nconst analysisEl = document.getElementById(\"analysis\");\n\nfunction renderAnalysis(skill) {\n  const scope = skill === \"all\" ? \"全部器物与命令\" : skill;\n  const goals = fixedGoals();\n  analysisEl.innerHTML =\n    `<div class=\"analysis\"><span class=\"tag\">固定分析目标 · ${esc(scope)}</span>` +\n    `<div class=\"qa-grid\">` + goals.map(g => `<div class=\"qa\"><div class=\"q\">${esc(g.title)}</div><p class=\"a\">${g.text}</p></div>`).join(\"\") + `</div>` +\n    `<div class=\"flow\">流程：取数 → 按目标裁剪 → 生成（结论先行、引用数字）→ 缓存 · 与自定义目标同一管线 · 意图画像已并入会话线索</div></div>`;\n}\n\nfunction renderFeed(skill) {\n  const records = skill === \"all\" ? DATA.records : DATA.records.filter(r => r.skill === skill);\n  document.getElementById(\"feed-count\").textContent = `简讯 · ${records.length} 条 · 一条一卡`;\n  if (records.length === 0) {\n    feedEl.innerHTML = `<div class=\"brief\"><div class=\"quote\">窗口内没有该条目的记录。</div></div>`;\n    return;\n  }\n  // 小红书式瀑布流：4 列，每张卡放进当前最矮的列，空位自动补齐\n  const COLS = 4;\n  const columns = Array.from({ length: COLS }, () => {\n    const col = document.createElement(\"div\");\n    col.className = \"mcol\";\n    return col;\n  });\n  const heights = new Array(COLS).fill(0);\n  for (const r of records) {\n    const [sigText, sigClass] = SIG[r.source] ?? [r.source, \"explicit\"];\n    const card = document.createElement(\"div\");\n    card.className = `brief ${sigClass}`;\n    card.innerHTML =\n      `<div class=\"top\"><span class=\"sig\">${sigText}</span>` +\n      `<span class=\"skill\">${esc(r.skill)}</span><span class=\"when\">${whenLabel(r.ts)}</span></div>` +\n      (r.digest ? `<div class=\"digest\">${esc(r.digest)}</div>` : \"\") +\n      (r.args ? `<div class=\"quote\">「${esc(r.args)}」</div>` : \"\") +\n      (r.sessionPreview ? `<div class=\"session\">当日正在办：${esc(r.sessionPreview)}</div>` : \"\");\n    const idx = heights.indexOf(Math.min(...heights));\n    columns[idx].appendChild(card);\n    heights[idx] += card.offsetHeight + 12;\n  }\n  feedEl.innerHTML = \"\";\n  columns.forEach(col => feedEl.appendChild(col));\n}\n\nfunction selectSkill(skill) {\n  [...indexEl.querySelectorAll(\"button\")].forEach(b => b.classList.toggle(\"active\", b.dataset.skill === skill));\n  renderAnalysis(skill);\n  renderFeed(skill);\n}\n\nconst counts = new Map();\nfor (const r of DATA.records) counts.set(r.skill, (counts.get(r.skill) ?? 0) + 1);\nconst entries = [{ skill: \"all\", total: DATA.records.length, zero: false }]\n  .concat([...counts.entries()].sort((a, b) => b[1] - a[1]).map(([skill, total]) => ({ skill, total, zero: false })));\n// 全量命令名录：零次的也入册（灰显），保证「能 slash 出来的」都在\nfor (const c of DATA.commandCatalog ?? []) {\n  if (!counts.has(c.name)) entries.push({ skill: c.name, total: 0, zero: true, desc: c.description });\n}\nindexEl.innerHTML = entries.map(e => {\n  const desc = e.desc ?? (e.skill === \"all\" ? \"窗口内全部记录\" : (DATA.descriptions?.[e.skill] ?? (DATA.commandCatalog ?? []).find(c => c.name === e.skill)?.description ?? \"\"));\n  const tipText = desc ? `${e.skill} · ${desc}` : e.skill;\n  return `<button data-skill=\"${esc(e.skill)}\" data-tip=\"${esc(tipText)}\" class=\"${e.zero ? \"zero\" : \"\"}\"><span>${esc(e.skill === \"all\" ? \"全部\" : e.skill)}</span><span class=\"n\">${e.total}</span></button>`;\n}).join(\"\");\nindexEl.addEventListener(\"click\", ev => {\n  const b = ev.target.closest(\"button\");\n  if (b) selectSkill(b.dataset.skill);\n});\n\n/* ——— 读者来信 ——— */\ndocument.getElementById(\"goals\").innerHTML = DATA.goals.map(g =>\n  `<div class=\"letter${g.tilt ? \" tilt\" : \"\"}\"><span class=\"who\">来件 · 分析目标</span>` +\n  `<h3>${esc(g.title)}</h3>` +\n  (g.pull ? `<div class=\"pull\">${esc(g.pull)}</div>` : \"\") +\n  `<p>${esc(g.text)}</p>` +\n  (g.aside ? `<div class=\"aside\">${esc(g.aside)}</div>` : \"\") +\n  `<span class=\"src\">${esc(g.src)}</span><div class=\"sign\">—— 登记于 ${esc(g.signedAt)}</div></div>`\n).join(\"\") || '<p class=\"note\">还没有自定义目标。</p>';\n\n/* ——— 目标推荐 ——— */\nconst LUCIDE_COPY = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect width=\"14\" height=\"14\" x=\"8\" y=\"8\" rx=\"2\" ry=\"2\"></rect><path d=\"M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2\"></path></svg>`;\nconst LUCIDE_PIN = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" x2=\"12\" y1=\"17\" y2=\"22\"></line><path d=\"M9 10.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24V16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V6h1a2 2 0 0 0 0-4H8a2 2 0 0 0 0 4h1z\"></path></svg>`;\nconst LUCIDE_PIN_OFF = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"2\" x2=\"22\" y1=\"2\" y2=\"22\"></line><line x1=\"12\" x2=\"12\" y1=\"17\" y2=\"22\"></line><path d=\"M9 10.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24V16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V6h1a2 2 0 0 0 0-4H8a2 2 0 0 0 0 4h1z\"></path></svg>`;\n\ndocument.getElementById(\"suggests\").innerHTML = DATA.suggests.map((s, i) => {\n  const cmd = `/hapi-metrics purpose ${s.title}`;\n  return `<div class=\"suggest\"><span class=\"no\">建议 ${i + 1}</span>` +\n    `<button class=\"copy-icon\" data-cmd=\"${esc(cmd)}\" data-tip=\"复制登记命令\" title=\"复制登记命令\">${LUCIDE_COPY}</button>` +\n    `<h4>${esc(s.title)}</h4>` +\n    `<p>${esc(s.why)}</p><span class=\"data\">数据面：${esc(s.dataNeeded)}</span></div>`;\n}).join(\"\");\ndocument.getElementById(\"suggests\").addEventListener(\"click\", async (event) => {\n  const button = event.target.closest(\"button.copy-icon\");\n  if (!button) return;\n  try { await navigator.clipboard.writeText(button.dataset.cmd); } catch {}\n  button.dataset.tip = \"已复制 ✓\";\n  button.style.color = \"var(--red)\";\n  setTimeout(() => { button.dataset.tip = \"复制登记命令\"; button.style.color = \"\"; }, 1600);\n});\n\n/* ——— 新到器物 ——— */\ndocument.getElementById(\"wares\").innerHTML = DATA.wares.map(w =>\n  `<div class=\"wares\"><div class=\"name\">${esc(w.name)}<span class=\"tag${w.tag === \"低频\" ? \" low\" : \"\"}\">${esc(w.tag)}</span></div>` +\n  `<p>${esc(w.intro)}</p><p>${esc(w.recommend)}</p><div class=\"how\">${esc(w.how)}</div></div>`\n).join(\"\") || '<p class=\"note\">没有闲置的已安装 skill。</p>';\n\n/* —— 本报更新 —— */\ndocument.getElementById(\"update-log\").innerHTML = DATA.updates.map(u =>\n  `<div class=\"update-item\"><span class=\"u-date\">${esc(u.date)}</span><span>${esc(u.text)}</span></div>`\n).join(\"\");\n\n/* 左索引与右栏等高 */\n(function syncIndexHeight() {\n  const column = document.querySelector(\".column\");\n  const sync = () => { indexEl.style.maxHeight = column.offsetHeight + \"px\"; };\n  requestAnimationFrame(sync);\n  window.addEventListener(\"resize\", sync);\n})();\n\nselectSkill(\"all\");\n\n/* 图钉钉住 */\n(function pinning() {\n  const section = document.getElementById(\"what-section\");\n  const button = document.getElementById(\"pin-btn\");\n  const PIN = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" x2=\"12\" y1=\"17\" y2=\"22\"></line><path d=\"M9 10.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24V16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V6h1a2 2 0 0 0 0-4H8a2 2 0 0 0 0 4h1z\"></path></svg>`;\n  const PIN_OFF = `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"2\" x2=\"22\" y1=\"2\" y2=\"22\"></line><line x1=\"12\" x2=\"12\" y1=\"17\" y2=\"22\"></line><path d=\"M9 10.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24V16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V6h1a2 2 0 0 0 0-4H8a2 2 0 0 0 0 4h1z\"></path></svg>`;\n  let pinned = false;\n  const column = document.querySelector(\".column\");\n  button.innerHTML = PIN;\n  button.addEventListener(\"click\", () => {\n    pinned = !pinned;\n    section.classList.toggle(\"pinned\", pinned);\n    document.body.classList.toggle(\"scroll-locked\", pinned);\n    if (pinned) {\n      // 钉住：整版撑满视口，索引与简讯同高，滚轮只作用于内部\n      indexEl.style.maxHeight = \"100%\";\n      indexEl.style.height = \"100%\";\n      section.scrollIntoView({ block: \"start\" });\n    } else {\n      indexEl.style.height = \"\";\n      indexEl.style.maxHeight = column.offsetHeight + \"px\";\n    }\n    button.innerHTML = pinned ? PIN_OFF : PIN;\n    button.dataset.tip = pinned ? \"取消钉住，恢复页面滚动\" : \"钉住本版：页面滚动停止，滚轮只作用于简讯\";\n  });\n})();\n";
/** 渲染报告：DATA 注入时转义 <，防 </script> 截断 */
export function renderSkillsReport(data) {
    const dataJson = JSON.stringify(data).replace(/</g, '\u003c');
    return '<!doctype html>\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8">\n<title>器物晚报 · skill 使用纪要</title>\n<style>'
        + REPORT_CSS
        + '</style>\n</head>\n'
        + REPORT_BODY
        + '\n<script>const DATA = ' + dataJson + ';\n' + REPORT_SCRIPT + '</script>\n</body>\n</html>\n';
}
